13: /// SurrealDB-backed CRDT checkpoint store.
14: ///
15: /// One `SurrealCrdtStore` is wired per deployment in `frf-gateway`. The caller
16: /// is responsible for calling `connect` + `use_ns` + `use_db` before passing
17: /// the client to this adapter.
18: ///
19: /// Schema (auto-created on first write — no migration required):
20: /// ```sql
21: /// DEFINE TABLE crdt_snapshots SCHEMAFULL;
22: /// DEFINE FIELD entity_id   ON crdt_snapshots TYPE string;
23: /// DEFINE FIELD tenant_id   ON crdt_snapshots TYPE string;
24: /// DEFINE FIELD encoded_hex ON crdt_snapshots TYPE string;
25: /// DEFINE FIELD version     ON crdt_snapshots TYPE int;
26: /// DEFINE INDEX idx_entity_tenant ON crdt_snapshots
27: ///     COLUMNS entity_id, tenant_id UNIQUE;
28: /// ```
29: /// The `UNIQUE` index means `checkpoint` is an UPSERT on the `(entity_id,
30: /// tenant_id)` pair — only one snapshot per entity is retained.
31: #[derive(Clone, Debug)]
32: pub struct SurrealCrdtStore {
33:     db: Surreal<Any>,
34: }
